def align_up(value: int, alignment: int) -> int:
    if value < 0 or value > 65535 or alignment < 1 or alignment > 65535:
        return -1
    if (alignment & (alignment - 1)) != 0:
        return -1
    result = (value + alignment - 1) & ~(alignment - 1)
    if result > 65535:
        return -1
    return result
